use crate::db::{CreateInventoryItemInput, Database, InventoryItem}; use tauri::State;
#[tauri::command] pub async fn get_inventory_items(company_id: String, db: State<'_, Database>) -> Result<Vec<InventoryItem>, String> { sqlx::query_as("SELECT * FROM inventory_items WHERE company_id = ? ORDER BY item_code").bind(company_id).fetch_all(db.pool()).await.map_err(|error| format!("查询存货档案失败: {error}")) }
#[tauri::command] pub async fn create_inventory_item(input: CreateInventoryItemInput, db: State<'_, Database>) -> Result<InventoryItem, String> { if input.item_code.trim().is_empty() || input.item_name.trim().is_empty() || input.unit.trim().is_empty() || input.tax_rate.is_some_and(|rate| !(0.0..=1.0).contains(&rate)) { return Err("存货编码、名称和单位不能为空，税率应在 0% 至 100% 之间".to_string()); } let id = uuid::Uuid::new_v4().to_string(); sqlx::query("INSERT INTO inventory_items (id, company_id, item_code, item_name, specification, unit, tax_rate, default_subject) VALUES (?, ?, ?, ?, ?, ?, ?, ?)").bind(&id).bind(&input.company_id).bind(input.item_code.trim()).bind(input.item_name.trim()).bind(input.specification.as_deref().map(str::trim).filter(|v| !v.is_empty())).bind(input.unit.trim()).bind(input.tax_rate).bind(input.default_subject.as_deref().map(str::trim).filter(|v| !v.is_empty())).execute(db.pool()).await.map_err(|error| format!("新增存货失败: {error}"))?; sqlx::query_as("SELECT * FROM inventory_items WHERE id = ? AND company_id = ?").bind(id).bind(&input.company_id).fetch_one(db.pool()).await.map_err(|error| format!("查询新增存货失败: {error}")) }
